        consent = _select(consents, access)
        if consent is None:
            results.append({"index": index, "allowed": False, "reason": "no_matching_consent"})
        else:
            results.append(
                {
                    "index": index,
                    "allowed": True,
                    "reason": "consent_granted",
                    "consent_id": consent["consent_id"],
                }
            )
    return results

