                    "subject_id": state["subject_id"],
                    "purposes": sorted(state["purposes"]),
                    "data_categories": sorted(state["data_categories"]),
                    "recipients": sorted(state["recipients"]),
                    "valid_from": state["valid_from_raw"],
                    "valid_until": state["valid_until_raw"],
